import contextlib
import io
import unittest

from textkit.cli import main
from textkit.rot import rot


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class RotTest(unittest.TestCase):
    def test_rot13_default_example(self):
        self.assertEqual(rot("Hello, World!", 13), "Uryyb, Jbeyq!")

    def test_wraps_around_the_alphabet(self):
        self.assertEqual(rot("xyz", 3), "abc")
        self.assertEqual(rot("XYZ", 3), "ABC")

    def test_keeps_case(self):
        self.assertEqual(rot("aZ", 1), "bA")

    def test_other_characters_unchanged(self):
        self.assertEqual(rot("0 1-2_!é ü\n", 5), "0 1-2_!é ü\n")

    def test_zero_is_identity(self):
        self.assertEqual(rot("Abc", 0), "Abc")

    def test_negative_n(self):
        self.assertEqual(rot("abc", -1), "zab")
        self.assertEqual(rot("Abc", -27), "Zab")

    def test_large_n(self):
        self.assertEqual(rot("abc", 26), "abc")
        self.assertEqual(rot("abc", 53), "bcd")

    def test_round_trip(self):
        self.assertEqual(rot(rot("Hello", 7), -7), "Hello")

    def test_float_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", 1.5)

    def test_string_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", "1")

    def test_bool_raises(self):
        with self.assertRaises(ValueError):
            rot("abc", True)
        with self.assertRaises(ValueError):
            rot("abc", False)


class RotCliTest(unittest.TestCase):
    def test_default_is_rot13(self):
        self.assertEqual(run("rot", "Hello, World!"), (0, "Uryyb, Jbeyq!\n", ""))

    def test_negative_n(self):
        self.assertEqual(run("rot", "abc", "--n", "-1"), (0, "zab\n", ""))

    def test_large_n(self):
        self.assertEqual(run("rot", "abc", "--n", "27"), (0, "bcd\n", ""))

    def test_float_n_exits_2(self):
        code, out, err = run("rot", "abc", "--n", "1.5")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_non_numeric_n_exits_2(self):
        code, out, err = run("rot", "abc", "--n", "x")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))


if __name__ == "__main__":
    unittest.main()
