from textkit.slug import slugify


def run(*argv):
    out, err = io.StringIO(), io.StringIO()
    with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
        code = main(list(argv))
    return code, out.getvalue(), err.getvalue()


class SlugifyTest(unittest.TestCase):
    def test_spec_examples(self):
        self.assertEqual(slugify("Héllo, Wörld!"), "hello-world")
        self.assertEqual(slugify("  C++ & Rust  "), "c-rust")
        self.assertEqual(slugify("a b", sep="_"), "a_b")

    def test_accents_fold_to_ascii(self):
        self.assertEqual(slugify("é"), "e")
        self.assertEqual(slugify("Crème Brûlée"), "creme-brulee")

    def test_other_non_ascii_is_dropped(self):
        self.assertEqual(slugify("a中b"), "ab")
        self.assertEqual(slugify("naïve 😀 day"), "naive-day")

    def test_lower_cases(self):
        self.assertEqual(slugify("ABC Def"), "abc-def")

    def test_runs_of_separators_collapse(self):
        self.assertEqual(slugify("a   b---c_.d"), "a-b-c-d")

    def test_no_leading_or_trailing_sep(self):
        self.assertEqual(slugify("--a b--"), "a-b")
        self.assertEqual(slugify("__x__", sep="_"), "x")

    def test_digits_kept(self):
        self.assertEqual(slugify("Py 3.12 notes"), "py-3-12-notes")

    def test_custom_sep(self):
        self.assertEqual(slugify("a b", sep="_"), "a_b")
        self.assertEqual(slugify("a b c", sep="--"), "a--b--c")

    def test_multi_char_sep_is_not_stripped(self):
        self.assertEqual(slugify("-a-", sep="--"), "a")
        self.assertEqual(slugify("a", sep="-_"), "a")

    def test_single_word(self):
        self.assertEqual(slugify("hello"), "hello")

    def test_empty_raises(self):
        with self.assertRaises(ValueError):
            slugify("")

    def test_nothing_left_raises(self):
        with self.assertRaises(ValueError):
            slugify("!!!")
        with self.assertRaises(ValueError):
            slugify("   ")
        with self.assertRaises(ValueError):
            slugify("中文")


class SlugCliTest(unittest.TestCase):
    def test_example(self):
        self.assertEqual(run("slug", "Héllo, Wörld!"), (0, "hello-world\n", ""))

    def test_sep_option(self):
        self.assertEqual(run("slug", "a b", "--sep", "_"), (0, "a_b\n", ""))

    def test_nothing_left_exits_2(self):
        code, out, err = run("slug", "!!!")
        self.assertEqual(code, 2)
        self.assertEqual(out, "")
        self.assertTrue(err.startswith("error: "))

    def test_json_output(self):
        code, out, _ = run("--json", "slug", "a b")
        self.assertEqual(code, 0)
        self.assertIn('"command": "slug"', out)
        self.assertIn('"a-b"', out)


if __name__ == "__main__":
    unittest.main()

